function report = rebuild_iecon2026_opf_video(mode,output_folder,varargin)
%REBUILD_IECON2026_OPF_VIDEO Rebuild the fixed IECON 2026 H21 reference video.
% One MATLAB entry file contains its waveform/metric functions and the exact
% Python layout/inspection support. Only adjacent packaged inputs are used.
%   rebuild_iecon2026_opf_video('check',OUT)
%   rebuild_iecon2026_opf_video('preview',OUT,'PythonExecutable',PYTHON_EXE)
%   rebuild_iecon2026_opf_video('full',OUT,'PythonExecutable',PYTHON_EXE)
% OUT must be an explicit nonsynchronized working folder. No figures or
% visible applications are opened. 'check' requires base MATLAB with JVM;
% rendering also requires the documented Python packages and FFmpeg tools.
% The MP4 represents quasi-steady reference cycles, not physical elapsed time.
% Current/voltage overshoots of the original LUT are preserved and identified.
% PUBLIC ENTRY AND MODES
%   report = rebuild_iecon2026_opf_video(mode, output_folder, Name, Value, ...)
%   'check'   Recompute all 9,973 progressive rows and all 600 display cycles.
%             Compare arrays and metrics; do not render frames or encode video.
%   'preview' Recompute the same context and render ten selected reference
%             frames near lookup/limit crossings, the late ramp and endpoints.
%   'full'    Recompute all 600 cycles, render and inspect every frame, then
%             encode and fully decode the 20 s / 30 fps / 2560 x 1440 MP4.
%   The returned report and JSON/log files record the checks that actually ran.
%   A preview or numerical check is not a full encoded-video verification.
%
% QUICK START (after extracting the complete archive)
%   Set the MATLAB current folder to IECON2026_OPFa_H21_package, then use:
%     out = fullfile(getenv('LOCALAPPDATA'),'IECON2026_H21_check_01');
%     report = rebuild_iecon2026_opf_video('check',out);
%   For rendering, also supply 'PythonExecutable' with the absolute path to
%   the documented Python environment. FFmpeg/FFprobe can be on PATH or set
%   through 'FFmpegExecutable' and 'FFprobeExecutable'. See README.md for the
%   complete dependency list and full/preview examples. Use a new output folder
%   after changing source, mode, runtime paths or StrictReference; run_binding
%   prevents unrelated or differently configured output from being overwritten.
%
% REQUIRED ADJACENT INPUTS (keep their original filenames and exact bytes)
%   LUTs_data_OPF_H21_nt250.mat       Full stored current-coefficient LUT.
%   IECON2026_OPFa_H21_inputs.mat     Paired trajectory, normalized EMF and
%                                   reference context/provenance structures.
%   STEP8_Video_frame_samples.csv    The 600 original indices/metric checks.
%   IECON2026_OPFa_H21_speed_ramp_video.mp4  Delivered reference for comparison.
%   The MP4 is required even in 'check'. A source-only GitHub checkout lacks
%   the large inputs: download and extract the complete reproduction archive.
%
% SCOPE AND NUMERICAL QUALIFICATIONS
%   Fixed case: six phases; phase a open; one isolated neutral; five pole
%   pairs; odd current harmonics 1,3,...,21; zero cogging torque (Tcog = 0).
%   This file reconstructs the paper's stored reference currents. It does not
%   solve the offline LP/QP or simulate a current controller or acceleration.
%   The original optimization used 250 electrical angles; the displayed
%   cycles use 16,000 angles. Peak/ripple metrics remain sampled quantities.
%   The 600 frames follow the original sample order. Their 20 s playback is
%   not physical trajectory time, and no physical time vector is invented.
%   'StrictReference' defaults to true: exact reference arrays/runtime/render
%   identities are required in the relevant mode. False keeps input hashes,
%   model/support guards and numerical tolerances, but relaxes exact reference
%   comparisons. It does not correct the LUT's physical constraint overshoots.
%   A reproduction PASS is compatible with FAIL_CURRENT_AND_VOLTAGE: the
%   separate full-path continuous-angle audit found small current/voltage
%   excesses. No clipping, coefficient scaling or neutral projection hides
%   them. See README.md and the included Step-5 report for the quantified audit.
%
% SOURCE MAP
%   Main entry: guarded loading, trajectory selection, checks and orchestration.
%   load_model / interpolate_coefficients / reconstruct / normalized_emf:
%     the common scientific waveform calculation, with units and shapes below.
%   iecon2026_opf_cycle_metrics: metrics from those exact waveform arrays.
%   pkg_payload: frozen Python helpers and definition embedded in this file;
%     readable matching copies are supplied under rendering_support/.
%   SOURCE_GUIDE.md maps the files, functions, outputs and safe adaptation rules.
%   Local functions are implementation details; call the public entry above.
assert(nargin>=2,'IECON2026Package:Arguments','Specify mode and a nonsynchronized output folder; see README.txt.');
mode=validatestring(char(mode),{'check','preview','full'});
%% Options and package/output ownership
% Rendering tools are explicit executable paths, not commands evaluated by a
% shell. StrictReference controls reproduction checks; it never changes the
% stored operating points or the waveform formula. 'check' needs only base
% MATLAB with JVM; rendering additionally uses Windows .NET and Python.
p=inputParser;
p.addParameter('PythonExecutable','',@(x)ischar(x)||isStringScalar(x));
p.addParameter('FFmpegExecutable','',@(x)ischar(x)||isStringScalar(x));
p.addParameter('FFprobeExecutable','',@(x)ischar(x)||isStringScalar(x));
p.addParameter('StrictReference',true,@(x)islogical(x)&&isscalar(x));
p.parse(varargin{:});options=p.Results;
assert(ispc,'IECON2026Package:Platform','The hidden process launcher is verified on Windows.');
[~,~,byte_order]=computer;
assert(byte_order=='L','IECON2026Package:ByteOrder','Reference array fingerprints use little-endian double values.');
package_folder=pkg_canonical(fileparts(mfilename('fullpath')));
output_folder=pkg_canonical(char(output_folder));
assert(~contains(lower(output_folder),'onedrive'),'IECON2026Package:Storage','Keep generated files outside OneDrive.');
assert(~pkg_under(output_folder,package_folder),'IECON2026Package:Storage','Use a working folder outside the read-only package.');
% The embedded definition fixes scientific configuration, original input
% hashes, selected indices, reference metrics/pixels and helper identities.
% Absolute historical paths in adjacent provenance files are not read here.
D=jsondecode(native2unicode(pkg_payload('definition'),'UTF-8'));
assert(strcmp(D.configuration_id,'IECON2026_OPFa_H21_full_nt250_Tcog0'));
assert(D.selection.full_frame_count==600 && D.selection.native_angle_count==16000 && D.selection.frames_per_second==30);
assert(~D.selection.physical_time_invented && ~D.selection.playback_time_is_physical_simulation_time);
for k=1:numel(D.runtime_inputs)
    item=D.runtime_inputs(k);file=pkg_canonical(fullfile(package_folder,item.name));
    assert(pkg_under(file,package_folder) && isfile(file),'IECON2026Package:InputMissing','Missing packaged input: %s',item.name);
    assert(strcmp(pkg_sha(file),item.sha256),'IECON2026Package:InputHash','Packaged input differs: %s',item.name);
end
% Bind each output folder to this exact entry file, mode, inputs and runtime
% paths. Even a comments-only source revision has a different file hash and
% must use a fresh output folder. Reuse is accepted only for the same binding.
entry_file=[mfilename('fullpath') '.m'];
binding=struct('configuration_id',D.configuration_id,'mode',mode,'strict_reference',options.StrictReference, ...
    'entry_SHA256',pkg_sha(entry_file),'runtime_inputs',{D.runtime_inputs}, ...
    'python_executable',char(options.PythonExecutable),'ffmpeg_path',char(options.FFmpegExecutable), ...
    'ffprobe_path',char(options.FFprobeExecutable));
if isfolder(output_folder)
    prior=fullfile(output_folder,'run_binding.json');
    assert(isfile(prior) && isequaln(jsondecode(fileread(prior)),binding), ...
        'IECON2026Package:OutputOwnership','Existing output folder has different or unknown ownership; use a new folder.');
else
    mkdir(output_folder);pkg_write(fullfile(output_folder,'run_binding.json'),binding);
end
pkg_write(fullfile(output_folder,'runtime_definition.json'),D);
%% Rendering preflight (preview/full only)
% Extract the embedded support only into the owned output folder. Its bytes
% must match the embedded hashes. Preflight checks the rendering environment
% before any expensive MATLAB cycle calculation begins.
if ~strcmp(mode,'check')
    assert(isfile(char(options.PythonExecutable)) && ~contains(lower(char(options.PythonExecutable)),'windowsapps'), ...
        'IECON2026Package:Python','Supply a real absolute Python executable; see README.txt.');
    support=fullfile(output_folder,'support');if ~isfolder(support),mkdir(support);end
    for pair={{'renderer','exact_layout.py'},{'inspector','exact_inspector.py'},{'driver','package_driver.py'}}
        name=pair{1}{1};file=fullfile(support,pair{1}{2});bytes=pkg_payload(name);
        assert(strcmp(pkg_digest(bytes),D.support_payload_SHA256.(name)));
        if isfile(file),assert(strcmp(pkg_sha(file),pkg_digest(bytes)));else,pkg_bytes(file,bytes);end
    end
    pkg_python('preflight',[],package_folder,output_folder,options);
    native_folder=fullfile(output_folder,'native_batch');if ~isfolder(native_folder),mkdir(native_folder);end
end
%% Load the exact scientific case and retained trajectory
% The 1,443,053 original speed/torque samples are paired and kept in order.
% The selected contiguous prefix is indices 1:1,314,036, ending immediately
% before the first sample above 1500 r/min. Requested and used points are
% identical: no speed/torque sorting, smoothing, resampling or saturation.
% The approximately 849.87 r/min minimum is a retained original fluctuation.
M=load_model(package_folder,D);
B=load(fullfile(package_folder,'IECON2026_OPFa_H21_inputs.mat'),'speed_m2','torque_m2','trajectory','angleEMF','backEMF');
assert(numel(B.speed_m2)==1443053 && numel(B.torque_m2)==1443053);
assert(isequal(B.speed_m2(1:1314036),M.trajectory.speed_used_rpm));
assert(isequal(B.torque_m2(1:1314036),M.trajectory.torque_used_Nm));
assert(B.speed_m2(1314036)<=1500 && B.speed_m2(1314037)>1500);
assert(isequal(double(M.trajectory.source_index_1based(:)),(1:1314036).'));
for name={'speed_m2','torque_m2','angleEMF','backEMF'}
    assert(strcmp(pkg_array_sha(B.(name{1})),D.original_array_sha256.(name{1})), ...
        'IECON2026Package:OriginalArray','Merged original array differs: %s',name{1});
end
% Deliberately reject the first excluded point, whose bounding support fails.
caught=false;
try
    interpolate_coefficients(M,B.speed_m2(1314037),B.torque_m2(1314037));
catch err
    assert(strcmp(err.identifier,'IECON2026:InterpolationSupport'), ...
        'IECON2026Package:BoundaryGuard','Unexpected excluded-point error: %s',err.identifier);
    caught=true;
end
assert(caught,'IECON2026Package:BoundaryGuard','The unsupported first excluded point was accepted.');
clear B
%% Recompute progressive traces and select displayed samples
% Recalculate the left-column context with the SAME waveform/metric functions
% as the right-column cycles. Stored context values are comparison references,
% not an alternate source of live display metrics.
context_report=pkg_rebuild_plot_context(M,package_folder,output_folder,options.StrictReference);
REF=readtable(fullfile(package_folder,'STEP8_Video_frame_samples.csv'), ...
    'TextType','string','VariableNamingRule','preserve');
assert(height(REF)==600 && width(REF)==24);
all_ids=double(D.selection.source_indices_1based(:));
assert(isequal(all_ids,floor(linspace(1,1314036,600).'+0.5)));
assert(isequal(double(REF.source_index_1based),all_ids));
% floor(linspace(...)+0.5) selects 600 existing samples across the retained
% prefix; it does not generate interpolated operating points. Frame k starts
% at (k-1)/30 s of playback. Preview frame IDs are a subset of these same 600.
% The first displayed voltage/current excesses occur at frames 302/515;
% these are not exact continuous-path or optimization active-set transitions.
if strcmp(mode,'preview')
    frame_ids=[1 119 120 301 302 514 515 531 533 600].';
else
    frame_ids=(1:600).';
end
% One electrical cycle has uniform angles 2*pi/N,...,2*pi: exclude zero so
% the periodic endpoint is counted once. Even N supports exact half-cycle
% pairing. The renderer presents the cycle over 0-360 electrical degrees.
theta=(1:16000).'*2*pi/16000;
fields={'configuration_id','harmonic_orders','phase_displacements_rad', ...
    'source_index_1based','speed_requested_rpm','speed_used_rpm', ...
    'torque_requested_Nm','torque_used_Nm','f1_actual_Hz','f1_lookup_Hz', ...
    'first_column_lookup_applied','theta_e_rad','currents_A','back_emf_V', ...
    'line_voltage_V','torque_Nm','cogging_torque_Nm','IRe_A','IIm_A', ...
    'physical_saturation_applied','neutral_coefficients_projected', ...
    'physical_time_vector_present','quasi_steady'};
array_fields={'theta_e_rad','currents_A','back_emf_V','line_voltage_V','torque_Nm','IRe_A','IIm_A'};
records=struct('frame_1based',{},'source_index_1based',{},'maximum_metric_error',{}, ...
    'all_seven_original_array_fingerprints_match',{},'actual_array_SHA256',{}, ...
    'open_phase_current_exactly_zero',{},'neutral_peak_A',{});
batch=[];timer=tic;total_errors=zeros(1,17);all_arrays=true;
%% Reconstruct, measure and verify the common cycles
% W contains the actual cycle arrays; Q reduces those arrays into measurements.
% Each cycle is checked against 17 reference scalars and seven native-array
% SHA-256 fingerprints. A finer angular grid alone is not a continuous-angle
% peak certificate. The separate full-path audit is not rerun by this entry.
for ordinal=1:numel(frame_ids)
    k=frame_ids(ordinal);W=iecon2026_opf_waveforms('cycle',M,all_ids(k),theta);
    Q=iecon2026_opf_cycle_metrics(M,W);
    [errors,tolerances]=pkg_metric_comparison(REF,k,W,Q);
    assert(all(errors<=tolerances),'IECON2026Package:Metrics','Cycle metrics differ at frame %d.',k);
    total_errors=max(total_errors,errors);
    actual=struct;matches=true;
    for name=array_fields
        actual.(name{1})=pkg_array_sha(W.(name{1}));
        matches=matches && strcmp(actual.(name{1}),D.gold_frames(k).array_SHA256.(name{1}));
    end
    if options.StrictReference
        assert(matches,'IECON2026Package:WaveformFingerprint','An exact native waveform array differs at frame %d.',k);
    end
    all_arrays=all_arrays && matches;
    records(ordinal)=struct('frame_1based',k,'source_index_1based',all_ids(k), ...
        'maximum_metric_error',max(errors),'all_seven_original_array_fingerprints_match',matches, ...
        'actual_array_SHA256',actual,'open_phase_current_exactly_zero',all(W.currents_A(:,:,1)==0,'all'), ...
        'neutral_peak_A',max(abs(sum(W.currents_A,3)),[],'all'));
%     Send only the fields needed by the frozen renderer, without changing
%     their numbers. Batches of at most 25 avoid keeping all full cycles in
%     memory. Each exact transient MAT is removed only after its rendered
%     frame and scientific/artist comparisons pass; reviewed PNGs remain.
    if ~strcmp(mode,'check')
        complete_W=W;complete_Q=Q;W=struct;
        for name=fields,W.(name{1})=complete_W.(name{1});end
        Q=rmfield(complete_Q,{'vsd_current_A','dq1_current_A','theta_e_rad'});
        video_frame=struct('id',sprintf('video_%04d',k),'title','Preserved ramp', ...
            'video_frame_1based',k,'source_index_1based',all_ids(k),'W',W,'Q',Q);
        native_path=fullfile(native_folder,sprintf('cycle_%04d.mat',k));
        save(native_path,'video_frame','-v7');batch(end+1)=k; %#ok<AGROW>
        clear complete_W complete_Q video_frame
        if numel(batch)==25 || ordinal==numel(frame_ids)
            pkg_python('batch',batch,package_folder,output_folder,options);
            reviewed=jsondecode(fileread(fullfile(output_folder,'last_batch_review.json')));
            assert(strcmp(reviewed.result,'PASS_PACKAGE_RENDERED_BATCH') && isequal(double(reviewed.frame_ids(:)),batch(:)));
            for j=batch
                exact_file=pkg_canonical(fullfile(native_folder,sprintf('cycle_%04d.mat',j)));
                assert(pkg_under(exact_file,native_folder) && isfile(exact_file));
                % Only our exact transient cycle file is removed after its
                % rendered frame and scientific comparison have passed.
                delete(exact_file);
            end
            batch=[];
        end
    end
    if mod(ordinal,25)==0 || ordinal==numel(frame_ids)
        fprintf('PASS packaged native cycles %d/%d (%.1f s); original inputs and coefficients preserved.\n',ordinal,numel(frame_ids),toc(timer));
    end
end
%% Write reports and verify that source inputs stayed unchanged
% Reports distinguish numerical reproduction from physical feasibility.
% Current/voltage overshoots are preserved; a faithful calculation therefore
% must retain the scientific failure flag rather than infer feasibility from
% a reproduction PASS. Only full mode encodes and checks the complete MP4.
native_report=struct('result','PASS_PACKAGED_NATIVE_CYCLE_REPRODUCTION','mode',mode, ...
    'configuration_id',D.configuration_id,'frame_count',numel(frame_ids),'frame_ids',frame_ids, ...
    'native_angle_count',16000,'metric_scalar_comparisons',numel(frame_ids)*17, ...
    'waveform_array_comparisons',numel(frame_ids)*7,'maximum_metric_errors',total_errors, ...
    'all_seven_arrays_match_original_at_every_checked_frame',all_arrays, ...
    'strict_reference',options.StrictReference,'records',records,'matlab_version',version, ...
    'progressive_context_verification',context_report, ...
    'exact_original_sample_order_and_values_preserved',true,'first_excluded_support_guard_passed',caught, ...
    'physical_saturation_applied',false,'neutral_coefficients_projected',false, ...
    'physical_time_invented',false,'scientific_limit_compliance','FAIL_CURRENT_AND_VOLTAGE', ...
    'recording_ready_with_all_limits_claim',false,'source_path_policy','Only adjacent packaged inputs are read', ...
    'elapsed_seconds',toc(timer));
pkg_write(fullfile(output_folder,'native_verification.json'),native_report);
if strcmp(mode,'full')
    pkg_python('encode',[],package_folder,output_folder,options);
    report=jsondecode(fileread(fullfile(output_folder,'reproduction_review.json')));
elseif strcmp(mode,'preview')
    report=native_report;report.result='PASS_PACKAGED_SELECTED_PREVIEW_FRAMES';
else
    report=native_report;
end
for k=1:numel(D.runtime_inputs)
    item=D.runtime_inputs(k);assert(strcmp(pkg_sha(fullfile(package_folder,item.name)),item.sha256));
end
assert(strcmp(pkg_sha(entry_file),binding.entry_SHA256));
fprintf('PASS: %s. Output: %s\n',report.result,output_folder);
end

function report=pkg_rebuild_plot_context(M,package_folder,output_folder,strict)
% PKG_REBUILD_PLOT_CONTEXT Regenerate the progressive traces from native cycles.
% The 9,973 context source IDs are original trajectory samples and include
% the endpoint. Batches of 24 preserve the verified reduction order (important
% for bit-exact comparison). Arrays are [point, angle, phase/line]; reduction
% over dimension 2 gives one metric per operating point. All 19 context
% fields, including per-phase/per-line arrays, are checked after calculation.
% Same 24-point batches, angle grid and reductions as the verified Step-6
% preparer; the stored context is used only for IDs and reference checks.
B=load(fullfile(package_folder,'IECON2026_OPFa_H21_inputs.mat'),'plot_data');
reference=B.plot_data;ids=double(reference.source_index_1based(:));
assert(numel(ids)==9973 && ids(1)==1 && ids(end)==1314036 && all(diff(ids)>0));
assert(reference.angle_samples==16000);
theta=(1:16000).'*2*pi/16000;
scalar_fields={'mean_torque_Nm','torque_min_Nm','torque_max_Nm','torque_ripple_pp_Nm', ...
    'peak_phase_current_A','peak_phase_index_1based','peak_line_voltage_V', ...
    'peak_line_pair_index_1based','copper_loss_W','id1_A','iq1_A'};
plot_data=reference;
for k=1:numel(scalar_fields),plot_data.(scalar_fields{k})=zeros(numel(ids),1);end
plot_data.phase_rms_current_A=zeros(numel(ids),6);
plot_data.phase_peak_current_A=zeros(numel(ids),6);
plot_data.line_peak_voltage_V=zeros(numel(ids),10);
timer=tic;batch=24;
for first=1:batch:numel(ids)
    last=min(first+batch-1,numel(ids));range=first:last;
    W=iecon2026_opf_waveforms('cycle',M,ids(range),theta);
    Q=iecon2026_opf_cycle_metrics(M,W);
    for k=1:numel(scalar_fields),plot_data.(scalar_fields{k})(range)=Q.(scalar_fields{k});end
    plot_data.phase_rms_current_A(range,:)=Q.phase_rms_current_A;
    plot_data.phase_peak_current_A(range,:)=Q.phase_peak_current_A;
    plot_data.line_peak_voltage_V(range,:)=Q.line_peak_voltage_V;
    if mod(first-1,batch*25)==0 || last==numel(ids)
        fprintf('Rebuilt progressive metrics: %d/%d original rows (%.1f s).\n',last,numel(ids),toc(timer));
    end
end
fields=fieldnames(plot_data);comparisons=struct;fingerprints=struct;exact=true;
for k=1:numel(fields)
    name=fields{k};error_value=max(abs(plot_data.(name)-reference.(name)),[],'all');
    tolerance=2e-10;if contains(name,'voltage'),tolerance=2e-8;end
    assert(error_value<=tolerance,'IECON2026Package:PlotContext','Progressive field differs: %s',name);
    matches=isequaln(plot_data.(name),reference.(name));exact=exact && matches;
    comparisons.(name)=struct('maximum_error',error_value,'tolerance',tolerance,'bit_exact',matches);
    fingerprints.(name)=pkg_array_sha(plot_data.(name));
end
if strict,assert(exact,'IECON2026Package:PlotContextFingerprint','The regenerated progressive data is not bit exact.');end
frame_data=struct('plot_data',plot_data,'configuration_id',M.configuration_id);
save(fullfile(output_folder,'rebuilt_plot_context.mat'),'frame_data','-v7');
report=struct('result','PASS_ALL_PROGRESSIVE_CONTEXT_ROWS_REBUILT','rows',9973, ...
    'angle_samples',16000,'all_fields_bit_exact',exact,'comparisons',comparisons, ...
    'rebuilt_field_SHA256',fingerprints,'elapsed_seconds',toc(timer), ...
    'reused_stored_metric_values_without_recalculation',false);
pkg_write(fullfile(output_folder,'progressive_context_verification.json'),report);
clear B W Q
end

function [errors,tolerances]=pkg_metric_comparison(R,k,W,Q)
% PKG_METRIC_COMPARISON Check frame identity, units, metric values and extrema.
% The 17 scalars include five separate healthy-phase RMS currents and signed
% current/voltage excesses. Excess = measured peak minus its prescribed cap;
% it is not a clipped or corrected value. Voltage comparisons allow 2e-8 V;
% other scalar errors allow 2e-10 in their own units. Parseval separately checks
% the RMS calculation without substituting its result into the display.
assert(R.frame_1based(k)==k && R.source_index_1based(k)==W.source_index_1based && R.angle_samples(k)==16000);
assert(R.playback_time_s(k)==(k-1)/30);
actual=[W.speed_used_rpm,W.torque_used_Nm,Q.mean_torque_Nm,Q.torque_ripple_pp_Nm, ...
    Q.peak_phase_current_A,Q.peak_line_voltage_V,Q.phase_rms_current_A(2:6), ...
    Q.copper_loss_W,Q.id1_A,Q.iq1_A,max(abs(sum(W.currents_A,3)),[],'all'), ...
    Q.peak_phase_current_A-4.34,Q.peak_line_voltage_V-290];
expected=[R.speed_actual_rpm(k),R.torque_requested_Nm(k),R.mean_torque_Nm(k),R.torque_ripple_pp_Nm(k), ...
    R.peak_current_A(k),R.peak_healthy_line_voltage_V(k),R.RMS_b_A(k),R.RMS_c_A(k),R.RMS_d_A(k),R.RMS_e_A(k),R.RMS_f_A(k), ...
    R.copper_loss_W(k),R.id1_cycle_mean_A(k),R.iq1_cycle_mean_A(k),R.neutral_current_peak_A(k), ...
    R.current_excess_A(k),R.voltage_excess_V(k)];
errors=abs(actual-expected);tolerances=2e-10*ones(1,17);tolerances([6 17])=2e-8;
assert(isequal(W.speed_requested_rpm,W.speed_used_rpm) && isequal(W.torque_requested_Nm,W.torque_used_Nm));
phase=find('abcdef'==char(R.current_peak_phase(k)));
pair=find(strcmp(Q.line_voltage_pairs,char(R.voltage_peak_pair(k))));
assert(isscalar(phase) && phase>=2 && abs(Q.phase_peak_current_A(phase)-Q.peak_phase_current_A)<2e-10);
assert(isscalar(pair) && abs(Q.line_peak_voltage_V(pair)-Q.peak_line_voltage_V)<2e-8);
assert(max(abs(Q.phase_rms_current_A-Q.phase_rms_parseval_A))<2e-11);
end

function pkg_python(action,ids,package_folder,output_folder,options)
% PKG_PYTHON Run the exact embedded driver invisibly, without a command shell.
% 'preflight' checks dependencies; 'batch' renders/checks supplied MATLAB
% cycles; 'encode' makes the MP4 and inspects all decoded frames. Read stdout
% and stderr concurrently to avoid a filled pipe blocking the child process.
% Logs remain in the owned output folder; a nonzero child exit is a failure.
job=struct('action',action,'package_folder',package_folder,'output_folder',output_folder, ...
    'strict_reference',options.StrictReference,'frame_ids',ids, ...
    'ffmpeg_path',char(options.FFmpegExecutable),'ffprobe_path',char(options.FFprobeExecutable));
file=fullfile(output_folder,'python_job.json');pkg_write(file,job);
args={'-B',fullfile(output_folder,'support','package_driver.py'),'--job',file};
info=System.Diagnostics.ProcessStartInfo;
info.FileName=char(options.PythonExecutable);
info.Arguments=pkg_windows_arguments(args);
info.UseShellExecute=false;info.CreateNoWindow=true;
info.WindowStyle=System.Diagnostics.ProcessWindowStyle.Hidden;
info.RedirectStandardOutput=true;info.RedirectStandardError=true;
process=System.Diagnostics.Process;process.StartInfo=info;
assert(process.Start(),'IECON2026Package:Process','Could not start the hidden Python process.');
stdout_task=process.StandardOutput.ReadToEndAsync();
stderr_task=process.StandardError.ReadToEndAsync();
process.WaitForExit();
stdout_text=char(stdout_task.Result);stderr_text=char(stderr_task.Result);
pkg_append_text(fullfile(output_folder,['python_' action '_stdout.log']),stdout_text);
pkg_append_text(fullfile(output_folder,['python_' action '_stderr.log']),stderr_text);
if ~isempty(stdout_text),fprintf('%s',stdout_text);end
if ~isempty(stderr_text),fprintf(2,'%s',stderr_text);end
status=double(process.ExitCode);process.Dispose();
assert(status==0,'IECON2026Package:PythonFailure','Python action %s failed; inspect the output folder and captured batch log.',action);
end

function pkg_append_text(file,text)
% Append UTF-8 diagnostic text; onCleanup closes the exact file on errors too.
fid=fopen(file,'a','n','UTF-8');assert(fid>=0);cleanup=onCleanup(@()fclose(fid)); %#ok<NASGU>
fprintf(fid,'%s',text);
end

function out=pkg_windows_arguments(args)
% Quote each Windows process argument literally. This helper is for the .NET
% launcher, not for PowerShell/cmd; embedded quotes and newlines are rejected.
quoted=cell(size(args));
for k=1:numel(args)
    a=char(args{k});assert(isempty(regexp(a,'["\r\n]','once')));
    % No command shell is used. Windows trailing backslashes are doubled
    % before the closing quote according to the CRT argument convention.
    n=0;for j=numel(a):-1:1,if a(j)=='\',n=n+1;else,break;end,end
    quoted{k}=['"' a repmat('\',1,n) '"'];
end
out=strjoin(quoted,' ');
end

function path=pkg_canonical(path)
% Resolve an absolute canonical path before ownership/containment comparisons.
path=char(java.io.File(char(path)).getCanonicalPath());
end

function result=pkg_under(path,root)
% Use a separator boundary, so a sibling with a similar prefix is not accepted.
% Canonical Windows paths are compared without case sensitivity.
path=lower(pkg_canonical(path));root=lower(pkg_canonical(root));
result=strcmp(path,root) || startsWith(path,[root filesep]);
end

function out=pkg_array_sha(a)
% Hash the native, real double values in MATLAB column-major order a(:).
% Little-endian ordering is enforced by the entry; dimensions are checked
% separately. This is a scientific-array fingerprint, not a MAT-file checksum.
assert(isa(a,'double') && isreal(a));
out=pkg_digest(typecast(a(:),'uint8'));
end

function out=pkg_digest(bytes)
% SHA-256 of exact bytes; Java signed-byte conversion preserves all bit values.
md=java.security.MessageDigest.getInstance('SHA-256');
md.update(typecast(uint8(bytes(:)),'int8'));
out=lower(reshape(dec2hex(typecast(md.digest(),'uint8'),2).',1,[]));
end

function out=pkg_sha(file)
% Stream SHA-256 in 1 MiB blocks so large LUT/movie inputs need not be buffered.
assert(isfile(file),'IECON2026Package:HashFile','Missing exact file: %s',file);
md=java.security.MessageDigest.getInstance('SHA-256');
fid=fopen(file,'rb');assert(fid>=0);cleanup=onCleanup(@()fclose(fid)); %#ok<NASGU>
while ~feof(fid)
    bytes=fread(fid,1048576,'*uint8');md.update(typecast(bytes,'int8'));
end
out=lower(reshape(dec2hex(typecast(md.digest(),'uint8'),2).',1,[]));
end

function pkg_write(file,value)
% Write readable UTF-8 JSON; this function writes reports only, not inputs.
fid=fopen(file,'w','n','UTF-8');assert(fid>=0);cleanup=onCleanup(@()fclose(fid)); %#ok<NASGU>
fprintf(fid,'%s\n',jsonencode(value,'PrettyPrint',true));
end

function pkg_bytes(file,bytes)
% Write frozen helper bytes in binary mode to preserve their hash/line endings.
fid=fopen(file,'wb');assert(fid>=0);cleanup=onCleanup(@()fclose(fid)); %#ok<NASGU>
fwrite(fid,bytes,'uint8');
end


function out = iecon2026_opf_waveforms(action,varargin)
% Private packaged copy of the verified Step-3 waveform engine.
% Loading uses adjacent packaged inputs; annotations explain the calculation.
% Interpolation, reconstruction and back-EMF executable statements are unchanged.

% Private actions share one implementation: 'coefficients' selects retained
% trajectory IDs; 'cycle' reconstructs those points; 'point' accepts explicit
% speed/torque vectors for guarded diagnostics. The private 'load' action
% requires both folder and embedded definition D. These local functions are
% not standalone public scripts; use rebuild_iecon2026_opf_video to run them.
if nargin<1
    error('IECON2026:Arguments','An action is required; see help iecon2026_opf_waveforms.');
end
switch lower(string(action))
    case "load"
        must(numel(varargin)==2,'Arguments','The private loader requires the package folder and embedded definition.');
        out=load_model(char(varargin{1}),varargin{2});
    case "coefficients"
        must(numel(varargin)==2,'Arguments','coefficients requires a model and retained source indices.');
        model=varargin{1}; validate_model(model);
        ids=retained_indices(model,varargin{2});
        out=interpolate_coefficients(model,model.trajectory.speed_used_rpm(ids), ...
            model.trajectory.torque_used_Nm(ids));
        out.source_index_1based=model.trajectory.source_index_1based(ids);
        out.speed_requested_rpm=model.trajectory.speed_requested_rpm(ids);
        out.torque_requested_Nm=model.trajectory.torque_requested_Nm(ids);
        must(isequal(out.f1_lookup_Hz,model.trajectory.f1_lookup_Hz(ids)), ...
            'TrajectoryLookup','Computed lookup differs from the frozen Step-2 lookup.');
    case "cycle"
        must(numel(varargin)==2 || numel(varargin)==3,'Arguments','cycle requires a model, retained source indices and optional angle vector.');
        model=varargin{1}; validate_model(model);
        C=iecon2026_opf_waveforms('coefficients',model,varargin{2});
        theta=default_angles(model);
        if numel(varargin)==3, theta=varargin{3}; end
        out=reconstruct(model,C,theta);
    case "point"
        must(numel(varargin)==3 || numel(varargin)==4,'Arguments','point requires a model, actual speed, torque and optional angle vector.');
        model=varargin{1}; validate_model(model);
        C=interpolate_coefficients(model,varargin{2},varargin{3});
        theta=default_angles(model);
        if numel(varargin)==4, theta=varargin{4}; end
        out=reconstruct(model,C,theta);
    otherwise
        error('IECON2026:Action','Unknown action: %s.',string(action));
end
end

function model=load_model(folder,D)
% LOAD_MODEL Assemble the fixed machine, full LUT, trajectory and EMF data.
% LUT IRe/IIm are stored as single, size [303 torque, 532 electrical frequency,
% 6 phases, 11 odd harmonics]. They are promoted to double without modifying
% the stored MAT. Coefficients have units A; speed is mechanical r/min; LUT
% frequency is fundamental electrical Hz; torque is Nm; angles are radians.
% Healthy phases b-f have independent coefficients, and phase a stays zero.
must(isfolder(folder),'Folder','Packaged input folder does not exist.');
cfg=D.scientific_configuration;meta=struct('selection',D.trajectory_selection);
location='package';
data_path=fullfile(folder,'IECON2026_OPFa_H21_inputs.mat');
paths=struct('opf_full_H21_nt250',fullfile(folder,'LUTs_data_OPF_H21_nt250.mat'), ...
    'angle_emf',data_path,'back_emf',data_path);
L=load(paths.opf_full_H21_nt250,'IRe','IIm','Tref_array','f1_array', ...
    'f1Low','f1High','Tref_min','Tref_max','Tau_min','P','h','nt','nk', ...
    'K_o','K_a','C','G_prime','topology','Sym','Tcog','tau_mx','symmetrize_backEMF','backEMF_LUT_units', ...
    'e_halfwave_residual_raw','e_halfwave_residual','e_prime_peak_raw','e_prime_peak');
B=load(data_path,'trajectory','angleEMF','backEMF','configuration_id','input_schema_version');
must(B.input_schema_version==1 && strcmp(B.configuration_id,cfg.configuration_id),'PackageIdentity','Packaged input identity differs.');
T=B.trajectory;A=struct('angleEMF',B.angleEMF);E=struct('backEMF',B.backEMF);
must(cfg.machine.pole_pairs==5 && cfg.case.phase_count==6 && ...
    isequal(double(cfg.case.open_phase_indices(:)),1) && ...
    strcmp(cfg.case.neutral,'single_isolated_neutral') && ...
    strcmp(cfg.case.cogging_torque_mode,'zero'),'Case','Unsupported scientific case.');
must(cfg.lut.maximum_harmonic_order==21 && cfg.lut.offline_angle_samples_per_electrical_cycle==250 && ...
    isequal(double(cfg.lut.harmonic_orders(:).'),1:2:21),'Harmonics','Full H21/nt250 is required.');
must(strcmp(cfg.back_emf.periodic_interpolation,'linear') && cfg.back_emf.half_wave_symmetrization_required, ...
    'BackEMF','The selected OPF linear/half-wave processing is required.');
must(isa(L.IRe,'single') && isa(L.IIm,'single') && ...
    isequal(size(L.IRe),[303 532 6 11]) && isequal(size(L.IIm),size(L.IRe)), ...
    'LUTShape','The exact full float32 H21 LUT is required.');
must(double(L.P)==5 && double(L.nt)==250 && double(L.nk)==6 && ...
    isequal(double(L.h(:).'),1:2:21) && isequal(double(L.K_o(:)),1) && ...
    isequal(double(L.K_a(:).'),2:6) && double(L.topology)==0 && double(L.Sym)==1 && ...
    isequal(double(L.C),ones(1,6)) && all(L.Tcog(:)==0),'LUTCase','LUT metadata does not match the selected case.');
must(all(isfinite(L.IRe),'all') && all(isfinite(L.IIm),'all'), ...
    'Coefficients','Nonfinite LUT coefficients were found.');
must(all(L.IRe(:,:,1,:)==0,'all') && all(L.IIm(:,:,1,:)==0,'all'), ...
    'OpenPhase','Stored phase-a coefficients must be exactly zero.');
must(isequal(double(L.G_prime),double(cfg.physical_limits.G_prime)), ...
    'LinePairs','The complete ten healthy-terminal line pairs are required.');
must(logical(L.symmetrize_backEMF) && strcmp(char(L.backEMF_LUT_units),'V_per_rad_per_s'), ...
    'BackEMFUnits','Normalized mechanical-rad/s back-EMF with half-wave symmetry is required.');
must(strcmp(T.configuration_id,cfg.configuration_id) && ...
    T.physical_saturation_applied==0 && T.physical_time_vector_present==0 && ...
    numel(T.source_index_1based)==meta.selection.selected_pair_count, ...
    'Trajectory','Selected trajectory identity or treatment differs.');
must(isequal(T.speed_requested_rpm,T.speed_used_rpm) && ...
    isequal(T.torque_requested_Nm,T.torque_used_Nm),'Trajectory','Requested and used inputs must remain identical in this case.');

model=struct('engine_id','IECON2026_OPFa_H21_waveforms_v1','configuration_id',cfg.configuration_id, ...
    'source_location',location,'record_folder',folder,'source_paths',paths,'config',cfg,'trajectory',T);
model.h=double(L.h(:).');model.phi=double(cfg.case.phase_displacements_rad(:).');
must(max(abs(model.phi-(0:5)*pi/3))<1e-14,'PhaseConvention','Expected phi_k=(k-1)*pi/3.');
model.Taxis=double(L.Tref_array(:));model.Faxis=double(L.f1_array(:));
model.f1Low=double(L.f1Low(:));model.f1High=double(L.f1High(:));
model.Tmin=double(L.Tref_min(:));model.Tmax=double(L.Tref_max(:));
must(all(diff(model.Taxis)>0) && all(diff(model.Faxis)>0), ...
    'Axes','LUT axes must be strictly increasing.');
model.IRe=double(L.IRe);model.IIm=double(L.IIm);
% Construct the stored feasible-vertex mask using the envelope and Tau_min.
% Some unsupported vertices contain finite zero-filled coefficients, so a
% finite-value check alone would accept invalid interpolation support.
% This mask checks the stored sampled optimization support; it is not a
% continuous-angle physical-constraint certificate.
model.valid_cell=isfinite(model.f1Low) & isfinite(model.f1High) & ...
    isfinite(model.Tmin.') & isfinite(model.Tmax.') & ...
    model.Taxis>=model.Tmin.' & model.Taxis<=model.Tmax.' & ...
    model.Faxis.'<=model.f1High & isfinite(double(L.Tau_min)) & ...
    double(L.Tau_min)<=double(L.tau_mx);
% Paper VSD axis order: alpha, beta, x, y, 0+, 0-. Every resistance is 1.4 ohm;
% L diagonal is [0.012 0.012 0.0113 0.0113 0.0094 0.0094] H. The 0+ value is
% retained from source configuration; the paper specifies alpha-beta, x-y
% and 0- values. The single isolated neutral suppresses the ideal 0+ current.
% Use matrix left division to map VSD impedance back into the phase domain.
% Keep the complete model, including the open phase, when forming voltages.
model.D=double(cfg.machine.VSD_transform_D);
model.Rvsd=diag(double(cfg.machine.R_VSD_diagonal_ohm));
model.Lvsd=diag(double(cfg.machine.L_VSD_diagonal_H));
model.Rphase=model.D\(model.Rvsd*model.D);
model.Lphase=model.D\(model.Lvsd*model.D);
model.G=double(cfg.physical_limits.G_prime);
% The source EMF is e'_k = e_k/omega_m in V/(mechanical rad/s), NOT voltage
% per electrical speed. Its 126-point periodic table includes both 0 and 2*pi
% for interp1; the reconstructed cycle itself contains only one endpoint.
% The 250-angle fingerprint verifies the exact processing used by the LUT.
model.angleEMF=double(A.angleEMF(:));model.backEMF=double(E.backEMF(:));
must(numel(model.angleEMF)==126 && numel(model.backEMF)==126 && ...
    all(isfinite(model.angleEMF)) && all(isfinite(model.backEMF)) && ...
    all(diff(model.angleEMF)>0) && model.angleEMF(1)==0 && ...
    abs(model.angleEMF(end)-2*pi)<1e-14 && model.backEMF(1)==model.backEMF(end), ...
    'BackEMFGrid','Expected the complete periodic 126-point normalized waveform.');
% The 1e-5 A neutral guard detects inconsistent float32 coefficient data.
% It is a residual-consistency threshold, not permission to alter currents.
% The original small rounding residual is checked and never projected away.
model.neutral_guard_A=1e-5;
model.cos_hphi=cos(model.phi(:)*model.h);
model.sin_hphi=sin(model.phi(:)*model.h);
model.default_angle_count=250;
[raw,used,method]=normalized_emf(model,default_angles(model));
half=125;
measured=[max(abs(raw(1:half,:)+raw(half+1:end,:)),[],'all'), ...
    max(abs(used(1:half,:)+used(half+1:end,:)),[],'all'),max(abs(raw),[],'all'),max(abs(used),[],'all')];
stored=double([L.e_halfwave_residual_raw,L.e_halfwave_residual,L.e_prime_peak_raw,L.e_prime_peak]);
must(max(abs(measured-stored))<1e-12,'BackEMFFingerprint','Back-EMF processing does not match the LUT fingerprints.');
model.back_emf_fingerprint=struct('raw_halfwave_residual',measured(1), ...
    'used_halfwave_residual',measured(2),'raw_peak',measured(3),'used_peak',measured(4),'method',method);
model.physical_constraint_compliance_certified=false;
end

function C=interpolate_coefficients(model,speed,torque)
% INTERPOLATE_COEFFICIENTS Guarded bilinear interpolation of every phase/harmonic.
% Accept paired vectors or broadcast one scalar; return coefficients shaped
% [point, phase, harmonic]. Use the same weights for IRe and IIm. Never share
% a healthy phase's coefficient vector with another phase in this fault case.
must(isnumeric(speed) && isnumeric(torque) && isreal(speed) && isreal(torque) && ...
    isvector(speed) && isvector(torque) && ~isempty(speed) && ~isempty(torque), ...
    'OperatingPoints','Speed and torque must be nonempty real numeric vectors.');
speed=double(speed(:));torque=double(torque(:));
n=max(numel(speed),numel(torque));
if isscalar(speed),speed=repmat(speed,n,1);end
if isscalar(torque),torque=repmat(torque,n,1);end
must(numel(speed)==numel(torque) && all(isfinite(speed)) && all(isfinite(torque)), ...
    'OperatingPoints','Speed and torque must be finite and have compatible lengths.');
% With five pole pairs, f_e = 5*n/60. Below the first retained LUT column,
% only coefficient LOOKUP frequency is held at Faxis(1). Store factual and
% lookup separately: EMF and inductive voltage later use the actual n.
% This extrapolation rule is not a physical speed or torque saturation.
factual=speed*5/60;lookup=max(factual,model.Faxis(1));
must(all(speed>=0) && all(lookup<=model.Faxis(end)) && ...
    all(torque>=model.Taxis(1) & torque<=model.Taxis(end)), ...
    'Envelope','Operating point lies outside the stored axes or supported nonnegative speed range.');
hi_f=interp1(model.Taxis,model.f1High,torque,'linear');
lo_t=interp1(model.Faxis,model.Tmin,lookup,'linear');
hi_t=interp1(model.Faxis,model.Tmax,lookup,'linear');
must(all(isfinite(hi_f)) && all(isfinite(lo_t)) && all(isfinite(hi_t)) && ...
    all(factual<=hi_f) && all(torque>=lo_t & torque<=hi_t), ...
    'Envelope','Operating point is outside the stored feasible envelope; no silent saturation is applied.');
% An envelope pass does not ensure all four interpolation vertices are valid.
% Locate the bounding torque/frequency cell and its convex weights; inspect
% each nonzero-weight vertex below. At an exact breakpoint, a zero-weight
% outside vertex need not contribute, but no infeasible positive-weight
% vertex may be used. Unsupported points fail instead of being clipped.
it=discretize(torque,model.Taxis);jf=discretize(lookup,model.Faxis);
must(all(isfinite(it)) && all(isfinite(jf)),'Interpolation','A bounding cell was not found.');
ut=(torque-model.Taxis(it))./(model.Taxis(it+1)-model.Taxis(it));
uf=(lookup-model.Faxis(jf))./(model.Faxis(jf+1)-model.Faxis(jf));
weights=[(1-ut).*(1-uf),(1-ut).*uf,ut.*(1-uf),ut.*uf];
must(all(weights>=0 & weights<=1,'all') && max(abs(sum(weights,2)-1))<1e-14, ...
    'Interpolation','Expected convex bilinear interpolation weights.');
offsets=[0 0;0 1;1 0;1 1];
re=reshape(model.IRe,303*532,6,11);im=reshape(model.IIm,303*532,6,11);
C=struct('configuration_id',model.configuration_id,'source_index_1based',[], ...
    'speed_requested_rpm',speed,'speed_used_rpm',speed, ...
    'torque_requested_Nm',torque,'torque_used_Nm',torque, ...
    'f1_actual_Hz',factual,'f1_lookup_Hz',lookup,'first_column_lookup_applied',factual<model.Faxis(1), ...
    'physical_saturation_applied',false,'IRe_A',zeros(n,6,11),'IIm_A',zeros(n,6,11), ...
    'harmonic_orders',model.h,'phase_order',{{'a','b','c','d','e','f'}}, ...
    'corner_indices_1based',zeros(n,4,2),'corner_weights',weights);
for q=1:4
    rows=it+offsets(q,1);cols=jf+offsets(q,2);
    linear=sub2ind([303 532],rows,cols);active=weights(:,q)>0;
    must(all(model.valid_cell(linear(active))),'InterpolationSupport', ...
        'A nonzero-weight LUT vertex is infeasible; no zero-filled or extended vertex is used.');
    vertex_re=re(linear,:,:);vertex_im=im(linear,:,:);
    must(all(isfinite(vertex_re),'all') && all(isfinite(vertex_im),'all'), ...
        'Coefficients','A bounding vertex contains a nonfinite coefficient.');
    C.IRe_A=C.IRe_A+vertex_re.*reshape(weights(:,q),n,1,1);
    C.IIm_A=C.IIm_A+vertex_im.*reshape(weights(:,q),n,1,1);
    C.corner_indices_1based(:,q,1)=rows;C.corner_indices_1based(:,q,2)=cols;
end
must(all(C.IRe_A(:,1,:)==0,'all') && all(C.IIm_A(:,1,:)==0,'all'), ...
    'OpenPhase','Interpolated phase-a coefficients are not exactly zero.');
% Express sum_k i_k in global cos(h*theta)/sin(h*theta) coefficients. For
% each harmonic the residual amplitude is hypot(cosine,sine); summing those
% amplitudes bounds the neutral residual for EVERY electrical angle, beyond
% the sampled cycle. Preserve the interpolated coefficients after this check.
cosine=sum(C.IRe_A.*reshape(model.cos_hphi,1,6,11)-C.IIm_A.*reshape(model.sin_hphi,1,6,11),2);
sine=sum(C.IRe_A.*reshape(model.sin_hphi,1,6,11)+C.IIm_A.*reshape(model.cos_hphi,1,6,11),2);
C.neutral_cosine_coeff_A=reshape(cosine,n,11);
C.neutral_sine_coeff_A=reshape(sine,n,11);
C.neutral_angle_independent_bound_A=sum(hypot(C.neutral_cosine_coeff_A,C.neutral_sine_coeff_A),2);
must(all(C.neutral_angle_independent_bound_A<=model.neutral_guard_A), ...
    'Neutral','Neutral-current coefficient residual exceeds the float32 consistency guard.');
C.neutral_coefficients_projected=false;
end

function W=reconstruct(model,C,theta)
% RECONSTRUCT Create the one common cycle at fixed speed and torque.
% Waveforms are [point, angle, phase] or [point, angle, line]; torque is
% [point, angle]. theta is rotor electrical angle in radians. Phase numbering
% 1:6 is a:f and phi_k = (k-1)*pi/3, exactly as in the paper.
must(isnumeric(theta) && isreal(theta) && isvector(theta) && ~isempty(theta) && ...
    all(isfinite(theta(:))),'Angles','Angles must be a nonempty finite real vector in electrical radians.');
theta=double(theta(:));theta_periodic=mod(theta,2*pi);
n=numel(C.speed_used_rpm);nt=numel(theta);nh=numel(model.h);
[raw_e,eprime,emf_method]=normalized_emf(model,theta);
W=C;W.theta_e_rad=theta;W.phase_displacements_rad=model.phi;
W.currents_A=zeros(n,nt,6);W.di_dtheta_A_per_electrical_rad=zeros(n,nt,6);
% Paper current convention (IIm is the sine coefficient, with this sign):
%   i_k(theta) = sum_h [IRe(k,h)*cos(h*(theta-phi_k))
%                    + IIm(k,h)*sin(h*(theta-phi_k))], h = 1,3,...,21.
% Differentiate the harmonic series analytically in electrical angle; this
% avoids finite-difference errors in inductive voltage. At fixed operating
% point, di/dt = omega_e*di/dtheta. Derivatives of changing LUT coefficients
% during a physical acceleration are outside this quasi-steady calculation.
for k=1:6
    phase_theta=theta_periodic.'-model.phi(k);
    cosine=cos(model.h(:)*phase_theta);sine=sin(model.h(:)*phase_theta);
    a=reshape(C.IRe_A(:,k,:),n,nh);b=reshape(C.IIm_A(:,k,:),n,nh);
    W.currents_A(:,:,k)=a*cosine+b*sine;
    W.di_dtheta_A_per_electrical_rad(:,:,k)= ...
        a*(-model.h(:).*sine)+b*(model.h(:).*cosine);
end
must(all(W.currents_A(:,:,1)==0,'all'),'OpenPhase','Reconstructed phase-a current is not zero.');
W.neutral_current_A=sum(W.currents_A,3);
W.neutral_current_peak_A=max(abs(W.neutral_current_A),[],2);
must(all(W.neutral_current_peak_A<=C.neutral_angle_independent_bound_A+1e-12), ...
    'Neutral','Current sum exceeds the analytical coefficient bound and double-roundoff allowance.');
W.normalized_back_emf_V_per_mechanical_rad_per_s=eprime;
W.raw_normalized_back_emf_V_per_mechanical_rad_per_s=raw_e;
W.back_emf_processing=emf_method;
% Use ACTUAL mechanical speed for e_k = omega_m*e'_k, and actual electrical
% speed omega_e = 5*omega_m for the inductive term. This remains true when
% coefficients were looked up at the first LUT column. Phase a's induced EMF
% is retained even though its current is exactly zero.
W.omega_m_rad_per_s=C.speed_used_rpm*2*pi/60;
W.omega_e_rad_per_s=5*W.omega_m_rad_per_s;
W.back_emf_V=reshape(W.omega_m_rad_per_s,n,1,1).*reshape(eprime,1,nt,6);
% From the paper's D*v = R*D*i + L*d(D*i)/dt + D*e:
%   v = Rphase*i + Lphase*(omega_e*di/dtheta) + e.
% The common-mode voltage reference is immaterial to the constrained terminal
% differences. G_prime then forms every healthy-terminal line voltage v'_r.
W.phase_voltage_V=zeros(n,nt,6);
for r=1:6
    vr=zeros(n,nt);vl=zeros(n,nt);
    for k=1:6
        vr=vr+model.Rphase(r,k)*W.currents_A(:,:,k);
        vl=vl+model.Lphase(r,k)*W.di_dtheta_A_per_electrical_rad(:,:,k);
    end
    W.phase_voltage_V(:,:,r)=vr+W.omega_e_rad_per_s.*vl+W.back_emf_V(:,:,r);
end
% Paper nomenclature: v'_r is component r of v' = G_prime*v. In this open-phase
% case use all ten pairs bc,bd,be,bf,cd,ce,cf,de,df,ef in that order. Opposite-
% phase pairs alone, sufficient in the balanced healthy example, miss peaks.
W.line_voltage_V=zeros(n,nt,10);
for line=1:10
    for k=1:6
        W.line_voltage_V(:,:,line)=W.line_voltage_V(:,:,line)+model.G(line,k)*W.phase_voltage_V(:,:,k);
    end
end
W.line_voltage_pairs=model.config.physical_limits.constrained_line_voltage_pairs;
% Torque follows the paper's T = sum_k e'_k*i_k + Tcog. Here Tcog = 0, so
% the normalized EMF can be used directly and the result is in Nm. Do not
% multiply this expression by mechanical speed or the pole-pair count again.
W.torque_Nm=sum(W.currents_A.*reshape(eprime,1,nt,6),3);
W.cogging_torque_Nm=0;
W.physical_constraint_compliance_certified=false;
W.physical_time_vector_present=false;
W.quasi_steady=true;
end

function [raw,used,method]=normalized_emf(model,theta)
% NORMALIZED_EMF Match the LUT's periodic-linear, half-wave EMF processing.
% Phase-shift queries with the same theta-phi_k convention as the currents.
% Half-wave symmetry is e'(theta+pi) = -e'(theta), consistent with odd current
% harmonics and with limiting both positive and negative waveform peaks.
query=mod(double(theta(:))-model.phi,2*pi);
raw=interp1(model.angleEMF,model.backEMF,query,'linear');
nt=numel(theta);paired=false;
if mod(nt,2)==0
    half=nt/2;
    paired=max(abs(mod(theta(half+1:end)-theta(1:half),2*pi)-pi))<1e-11;
end
% For an even, half-cycle-paired grid, construct the second half as EXACTLY
% the negative of the first: 0.5*(raw(theta)-raw(theta+pi)). For other query
% grids evaluate the pi-shifted partner explicitly. Preserve raw and used
% EMF separately so the processing remains observable in the waveform struct.
if paired
    first=0.5*(raw(1:half,:)-raw(half+1:end,:));used=[first;-first];
    method='periodic_linear_then_exact_paired_half_wave';
else
    partner=interp1(model.angleEMF,model.backEMF,mod(query+pi,2*pi),'linear');
    used=0.5*(raw-partner);
    method='periodic_linear_then_pointwise_half_wave_extension';
end
must(all(isfinite(raw),'all') && all(isfinite(used),'all'),'BackEMF','Nonfinite back-EMF interpolation result.');
end

function theta=default_angles(model)
% The private default reproduces the original 250-angle LUT convention.
% The public entry explicitly overrides it with 16,000 angles for the video.
theta=(1:model.default_angle_count).'*2*pi/model.default_angle_count;
end

function ids=retained_indices(model,ids)
% Indices address the original retained contiguous prefix, not a resampled
% or sorted trajectory. Preserve the original speed/torque pairing exactly.
must(isnumeric(ids) && isreal(ids) && isvector(ids) && ~isempty(ids), ...
    'Indices','Retained original source indices must be a nonempty numeric vector.');
ids=double(ids(:));
must(all(isfinite(ids)) && all(ids==fix(ids)) && all(ids>=1) && ...
    all(ids<=numel(model.trajectory.source_index_1based)), ...
    'Indices','An index is outside the retained original interval.');
must(all(double(model.trajectory.source_index_1based(ids))==ids), ...
    'Indices','The selected trajectory is not the original contiguous prefix.');
end

function validate_model(model)
% Reject unrelated model structs before applying this fixed-case engine.
must(isstruct(model) && isscalar(model) && isfield(model,'engine_id') && ...
    strcmp(model.engine_id,'IECON2026_OPFa_H21_waveforms_v1'), ...
    'Model','Load a model using this common waveform function first.');
end

function must(condition,id,message,varargin)
% Named scientific failures make unsupported interpolation distinguishable
% from missing inputs and other calculation failures.
if ~isscalar(condition) || ~condition
    error(['IECON2026:' id],message,varargin{:});
end
end

function Q = iecon2026_opf_cycle_metrics(M,W)
%IECON2026_OPF_CYCLE_METRICS Derive displayed quantities from one common cycle.
% Q = iecon2026_opf_cycle_metrics(M,W)
% M is assembled privately from the package folder and embedded definition D.
% W is the SAME waveform struct used by the waveform panels. Internal example:
%   W = iecon2026_opf_waveforms('cycle',M,source_indices);
%   Q = iecon2026_opf_cycle_metrics(M,W);
%
% Mean torque, peak-to-peak ripple, peak phase current, copper loss, peak
% line voltage and every phase RMS are reduced from W's waveform arrays.
% All ten healthy-terminal line voltages are checked. No LUT of aggregate
% metrics is interpolated and no current or voltage is rescaled.
%
% W must contain uniformly spaced points for exactly one electrical cycle,
% with one endpoint only. At least 45 points are required for full H21 and
% fundamental rotating-frame current RMS without Fourier aliasing. Default
% Step-3 cycles have 250 points. Irregular/partial/duplicated cycles fail.
% Peak and torque metrics describe THIS sampled cycle; they do not certify
% continuous-angle physical limits. A finer grid requires a new W and Q.
%
% Every VSD axis comes from the complete six-phase current vector. The
% historical video display convention is preserved explicitly:
%   id1 = -i_alpha*cos(theta) - i_beta*sin(theta)
%   iq1 =  i_alpha*sin(theta) - i_beta*cos(theta)
% Thus id1/iq1 are the negatives of conventional Park d/q with angle theta.
% Their cycle means recover -IRe_1/+IIm_1 in the balanced special case.
% In the open-phase case the instantaneous d1/q1 are generally not constant.

metric_must(isstruct(M) && isscalar(M) && isfield(M,'engine_id') && ...
    strcmp(M.engine_id,'IECON2026_OPFa_H21_waveforms_v1'),'Model','Load the verified Step-3 model first.');
metric_must(isstruct(W) && isscalar(W),'Waveforms','W must be one common waveform struct.');
required={'configuration_id','harmonic_orders','theta_e_rad','phase_order', ...
    'currents_A','IRe_A','IIm_A','phase_voltage_V','line_voltage_V','line_voltage_pairs', ...
    'torque_Nm','normalized_back_emf_V_per_mechanical_rad_per_s','source_index_1based', ...
    'speed_requested_rpm','speed_used_rpm','torque_requested_Nm','torque_used_Nm', ...
    'f1_actual_Hz','f1_lookup_Hz','first_column_lookup_applied','physical_saturation_applied', ...
    'neutral_coefficients_projected','physical_time_vector_present','quasi_steady'};
metric_must(all(isfield(W,required)),'Waveforms','W lacks a required Step-3 waveform or provenance field.');
metric_must(strcmp(W.configuration_id,M.configuration_id) && ...
    strcmp(M.configuration_id,'IECON2026_OPFa_H21_full_nt250_Tcog0') && ...
    isequal(double(W.harmonic_orders(:).'),1:2:21) && ...
    isequal(string(W.phase_order(:)),string({'a';'b';'c';'d';'e';'f'})), ...
    'Configuration','The selected H21 phase-a-open waveform case is required.');
theta=double(W.theta_e_rad(:));nt=numel(theta);n=numel(W.speed_used_rpm);
metric_must(nt>=45 && isreal(theta) && all(isfinite(theta)) && ...
    max(abs(diff(theta)-2*pi/nt))<1e-11,'CycleGrid', ...
    'Use at least 45 increasing, uniformly spaced points for one electrical cycle; do not duplicate 0 and 2*pi.');
metric_must(n>=1 && isequal(size(W.currents_A),[n nt 6]) && ...
    isequal(size(W.phase_voltage_V),[n nt 6]) && ...
    isequal(size(W.line_voltage_V),[n nt 10]) && ...
    isequal(size(W.torque_Nm),[n nt]) && ...
    isequal(size(W.normalized_back_emf_V_per_mechanical_rad_per_s),[nt 6]) && ...
    isequal(size(W.IRe_A),[n 6 11]) && isequal(size(W.IIm_A),[n 6 11]), ...
    'Shape','Expected [point, angle, phase/line] waveforms and [point, phase, harmonic] coefficients.');
for field={'currents_A','phase_voltage_V','line_voltage_V','torque_Nm', ...
        'normalized_back_emf_V_per_mechanical_rad_per_s','IRe_A','IIm_A'}
    value=W.(field{1});
    metric_must(isnumeric(value) && isreal(value) && all(isfinite(value),'all'), ...
        'Finite','All waveform and coefficient values must be finite and real.');
end
metric_must(all(W.currents_A(:,:,1)==0,'all') && all(W.IRe_A(:,1,:)==0,'all') && ...
    all(W.IIm_A(:,1,:)==0,'all'),'OpenPhase','Phase-a current and coefficients must be exactly zero.');
metric_must(~W.physical_saturation_applied && ~W.neutral_coefficients_projected && ...
    ~W.physical_time_vector_present && W.quasi_steady && ...
    isequal(W.speed_requested_rpm,W.speed_used_rpm) && ...
    isequal(W.torque_requested_Nm,W.torque_used_Nm), ...
    'Treatment','Preserve the verified requested/used quasi-steady operating points without invented time or rescaling.');
metric_must(isequal(string(W.line_voltage_pairs(:)),string(M.config.physical_limits.constrained_line_voltage_pairs(:))) && ...
    isequal(string(W.line_voltage_pairs(:)),string({'bc';'bd';'be';'bf';'cd';'ce';'cf';'de';'df';'ef'})), ...
    'LineOrder','All ten healthy-terminal line voltages must be ordered bc,bd,be,bf,cd,ce,cf,de,df,ef.');
pairs=double(M.config.physical_limits.constrained_line_voltage_pairs_one_based);
for line=1:10
    difference=W.phase_voltage_V(:,:,pairs(line,1))-W.phase_voltage_V(:,:,pairs(line,2));
    metric_must(max(abs(difference-W.line_voltage_V(:,:,line)),[],'all')<1e-10, ...
        'LineConsistency','A line-voltage waveform disagrees with its healthy-terminal phase-voltage difference.');
end
torque_reference=sum(W.currents_A.*reshape(W.normalized_back_emf_V_per_mechanical_rad_per_s,1,nt,6),3);
metric_must(max(abs(torque_reference-W.torque_Nm),[],'all')<1e-10, ...
    'TorqueConsistency','Torque does not match the same current and normalized back-EMF cycle with Tcog=0.');
resistances=double(M.config.machine.R_VSD_diagonal_ohm(:));
metric_must(isequal(resistances,1.4*ones(6,1)),'Resistance','The selected case requires 1.4 ohm in every axis and phase.');
Rs=resistances(1);

Q=struct('metric_engine_id','IECON2026_OPFa_H21_cycle_metrics_v1', ...
    'configuration_id',W.configuration_id,'source_index_1based',W.source_index_1based, ...
    'speed_requested_rpm',W.speed_requested_rpm,'speed_used_rpm',W.speed_used_rpm, ...
    'torque_requested_Nm',W.torque_requested_Nm,'torque_used_Nm',W.torque_used_Nm, ...
    'f1_actual_Hz',W.f1_actual_Hz,'f1_lookup_Hz',W.f1_lookup_Hz, ...
    'first_column_lookup_applied',W.first_column_lookup_applied, ...
    'theta_e_rad',theta,'angle_sample_count',nt,'uniform_complete_cycle',true, ...
    'phase_order',{W.phase_order},'healthy_phase_indices_1based',2:6, ...
    'line_voltage_pairs',{W.line_voltage_pairs},'phase_resistance_ohm',Rs);
% Mean torque = arithmetic mean of the uniform complete cycle; tau is its
% maximum-minus-minimum torque, not RMS ripple or peak-to-mean deviation.
% Peak current is max over angle AND healthy phase of abs(i_k). Retain the
% phase and angle attaining each peak so plotted brackets can be checked.
Q.mean_torque_Nm=mean(W.torque_Nm,2);
[Q.torque_min_Nm,Q.torque_min_angle_index_1based]=min(W.torque_Nm,[],2);
[Q.torque_max_Nm,Q.torque_max_angle_index_1based]=max(W.torque_Nm,[],2);
Q.torque_ripple_pp_Nm=Q.torque_max_Nm-Q.torque_min_Nm;
[phase_peaks,phase_peak_angles]=max(abs(W.currents_A),[],2);
Q.phase_peak_current_A=reshape(phase_peaks,n,6);
Q.phase_peak_current_angle_index_1based=reshape(phase_peak_angles,n,6);
[Q.peak_phase_current_A,relative_phase]=max(Q.phase_peak_current_A(:,2:6),[],2);
Q.peak_phase_index_1based=relative_phase+1;
% Each phase gets its own RMS = sqrt(mean(i_k^2)); unbalanced b-f currents
% cannot be represented by one shared RMS value. Physical SCL in watts is
% Rs*sum_k RMS_k^2 (phase a contributes zero). normalized_copper_loss_A2 is
% the current-squared quantity before multiplication by Rs, not loss in W.
phase_mean_square=reshape(mean(W.currents_A.^2,2),n,6);
Q.phase_rms_current_A=sqrt(phase_mean_square);
Q.healthy_phase_rms_current_A=Q.phase_rms_current_A(:,2:6);
Q.normalized_copper_loss_A2=sum(phase_mean_square(:,2:6),2);
Q.copper_loss_W=Rs*Q.normalized_copper_loss_A2;
% v_pk = max over electrical angle and ALL TEN r of abs(v'_r). The paper's
% v'_r labels the waveform, while v_pk labels its scalar peak measurement.
[line_peaks,line_peak_angles]=max(abs(W.line_voltage_V),[],2);
Q.line_peak_voltage_V=reshape(line_peaks,n,10);
Q.line_peak_voltage_angle_index_1based=reshape(line_peak_angles,n,10);
[Q.peak_line_voltage_V,Q.peak_line_pair_index_1based]=max(Q.line_peak_voltage_V,[],2);

% Parseval is an independent diagnostic; displayed RMS/SCL above are from W.
% For the full odd-harmonic series, per-phase mean(i_k^2) equals
% 0.5*sum_h(IRe_kh^2 + IIm_kh^2) on a sufficient uniform grid. This diagnostic
% can detect inconsistent waveform/coefficient scaling or phase-RMS reductions.
% The nt>=45 requirement prevents aliasing of squared H21 and rotating-frame
% fundamental currents; it does not guarantee accurate continuous peaks.
coefficient_mean_square=reshape(0.5*sum(W.IRe_A.^2+W.IIm_A.^2,3),n,6);
Q.phase_rms_parseval_A=sqrt(coefficient_mean_square);
Q.rms_parseval_max_error_A=max(abs(Q.phase_rms_current_A-Q.phase_rms_parseval_A),[],2);
Q.copper_loss_parseval_W=Rs*sum(coefficient_mean_square(:,2:6),2);
Q.copper_loss_parseval_error_W=abs(Q.copper_loss_W-Q.copper_loss_parseval_W);
metric_must(all(Q.rms_parseval_max_error_A<2e-11) && ...
    all(Q.copper_loss_parseval_error_W<2e-9),'Parseval', ...
    'Waveform RMS/copper loss do not agree with the full H21 per-phase Parseval check.');

% The complete vector is transformed, including the open phase's exact zero.
D=double(M.D);
metric_must(isequal(D,double(M.config.machine.VSD_transform_D)),'VSD','VSD matrix differs from the frozen model configuration.');
Q.vsd_current_A=zeros(n,nt,6);
for axis=1:6
    for k=1:6
        Q.vsd_current_A(:,:,axis)=Q.vsd_current_A(:,:,axis)+D(axis,k)*W.currents_A(:,:,k);
    end
end
% Apply the documented negative-Park display convention to the complete
% alpha/beta waveforms. In this unbalanced case, balanced single-coefficient
% shortcuts would lose contributions from independent phases/harmonics.
% id1_A/iq1_A are cycle means of these instantaneous vectors; the retained
% left panels show those means even though 'cycle mean' is omitted visually.
rotor_angle=mod(theta,2*pi).';c=cos(rotor_angle);s=sin(rotor_angle);
alpha=Q.vsd_current_A(:,:,1);beta=Q.vsd_current_A(:,:,2);
Q.dq1_current_A=zeros(n,nt,2);
Q.dq1_current_A(:,:,1)=-alpha.*c-beta.*s;
Q.dq1_current_A(:,:,2)= alpha.*s-beta.*c;
Q.dq1_cycle_mean_A=reshape(mean(Q.dq1_current_A,2),n,2);
Q.dq1_cycle_rms_A=reshape(sqrt(mean(Q.dq1_current_A.^2,2)),n,2);
Q.dq1_cycle_ripple_pp_A=reshape(max(Q.dq1_current_A,[],2)-min(Q.dq1_current_A,[],2),n,2);
Q.id1_A=Q.dq1_cycle_mean_A(:,1);Q.iq1_A=Q.dq1_cycle_mean_A(:,2);
Q.dq1_standard_Park_cycle_mean_A=-Q.dq1_cycle_mean_A;
Q.dq1_display_convention='negative_of_standard_Park_dq_at_paper_rotor_angle';
Q.dq1_left_panel_quantity='cycle_mean_of_complete_vector_rotating_frame_current';
Q.dq1_right_panel_quantity='complete_instantaneous_rotating_frame_waveform_if_retained';
Q.metrics_reduced_from_same_waveform_arrays=true;
Q.aggregate_metric_LUT_interpolated=false;
Q.physical_saturation_applied=false;
Q.physical_time_vector_present=false;
Q.continuous_angle_physical_limits_certified=false;
Q.quasi_steady=true;
end

function metric_must(condition,id,message)
% Keep metric-consistency errors separate from waveform/interpolation errors.
if ~isscalar(condition) || ~condition
    error(['IECON2026Metrics:' id],message);
end
end

function bytes=pkg_payload(name)
% PKG_PAYLOAD Decode frozen support so the MATLAB entry remains self-contained.
% The long strings below are BASE64 SOURCE, not numerical current/EMF data.
% 'renderer': exact_layout.py, fixed layout/colours/fonts and artist checks.
% 'inspector': exact_inspector.py, probe/decode/frame-order/fidelity checks.
% 'driver': package_driver.py, preflight/render/encode orchestration.
% 'definition': immutable scientific/runtime/input and gold-reference metadata.
% Readable copies of the three Python sources are in rendering_support/.
% The readable IECON2026_OPFa_H21_package.json also holds runtime_definition.
% The entry executes THESE embedded bytes; editing a readable copy alone
% does not change the movie. A derivative that changes a payload must also
% update its identity and reference checks, then verify and label the result.
